DO $block$ DECLARE tbl text; mod text; BEGIN FOREACH tbl IN ARRAY ARRAY['clients','orders','order_items','shipments','pricelist_items','payables','receivables','cash_requests','expenses','tasks','team_members'] LOOP mod:=public.entity_module(tbl); EXECUTE format('DROP POLICY %I ON public.%I',tbl||'_select',tbl); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (deleted_at IS NULL AND public.can_access_tenant_module(tenant_id,%L))',tbl||'_select',tbl,mod); END LOOP; END $block$;
CREATE OR REPLACE FUNCTION public.can_access_tenant_module(p_tenant_id uuid,p_module text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_tenant_id=public.active_tenant_id() AND public.is_tenant_member(p_tenant_id) AND (public.has_tenant_role(p_tenant_id,'master') OR EXISTS(SELECT 1 FROM public.module_access a WHERE a.tenant_id=p_tenant_id AND a.user_id=auth.uid() AND a.module=p_module)) $$;
CREATE OR REPLACE FUNCTION public.create_shipment_atomic(p_order_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.orders; sid uuid; tid uuid:=public.active_tenant_id(); BEGIN IF NOT public.can_access_tenant_module(tid,'shipments') THEN RAISE EXCEPTION 'Modul Pengiriman tidak berizin'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order_id AND tenant_id=tid AND deleted_at IS NULL FOR UPDATE; IF o.id IS NULL THEN RAISE EXCEPTION 'Order tidak ditemukan'; END IF; SELECT id INTO sid FROM public.shipments WHERE order_id=o.id AND tenant_id=tid AND deleted_at IS NULL ORDER BY created_at LIMIT 1; IF sid IS NOT NULL THEN RETURN sid; END IF; INSERT INTO public.shipments(tenant_id,order_id,ship_to,section,do_number,delivery_date,stored_by,delivery_by) VALUES(tid,o.id,o.client_name,o.section,replace(replace(o.invoice_number,'/INV/','/DO/'),'INV/','DO/'),(now() AT TIME ZONE 'Asia/Jakarta')::date,o.created_by,o.created_by) RETURNING id INTO sid; RETURN sid; END $$;